  AvgCommunicate_121371_Content_7 = {Text = "呵。"},
  AvgCommunicate_121371_Content_8 = {
    Text = "虽然我要承认，她在之前的选择和运气，或许比我好了那么一丁点。"
  },
  AvgCommunicate_121371_Content_9 = {
    Text = "但她应当明白，对命运的反抗，不是每一次都能成功。"
