    Text = "怎么了？"
  },
  AvgCommunicate_121372_Content_3 = {
    Text = "简直无法理喻！弥萨格为什么会让这种生物进入宿舍！"
  },
  AvgCommunicate_121372_Content_4 = {
    Text = "等等，我听到宿舍楼里有人在发出尖叫，是你吗？"
  },
  AvgCommunicate_121372_Content_5 = {
    Text = "怎么会有这么多猫聚在门口！？"
  },
  AvgCommunicate_121372_Content_6 = {
    Text = "这些邪恶阴险的小东西从我露面就开始尾随，一定有什么阴谋，它们要谋害王女！"
  },
  AvgCommunicate_121372_Content_7 = {
    Text = "……我觉得要谋害某人的邪恶生物应该，不会躺在地上翻出肚皮。"
  },
  AvgCommunicate_121372_Content_8 = {
    Text = "猫似乎喜欢你喜欢得有些异乎寻常。"
  },
  AvgCommunicate_121372_Content_9 = {
    Text = "一派胡言，我以王女的身份命令你，马上把它们赶出去，否则，我就、我就……"
  },
  AvgCommunicate_121372_Option_10 = {Text = "我就"},
  AvgCommunicate_121372_Option_11 = {Text = "你就"},
  AvgCommunicate_121375_Content_1 = {
    Text = "我知道你想说什么，祂们是自愿的。"
  },
  AvgCommunicate_121375_Content_10 = {
