  AvgCommunicate_121375_Content_14 = {Text = "嗯？"},
  AvgCommunicate_121375_Content_15 = {
    Text = "……好了我知道了我不做有的是鱼做。"
  },
  AvgCommunicate_121375_Content_16 = {
    Text = "我这就去，不要再让弥萨格出现更多鱼头了。"
  },
  AvgCommunicate_121375_Content_2 = {
    Text = "虽然不知道你是怎么联系上祂们的，但你不能再让海嗣出现在弥萨格，替你跑腿，排队，甚至写作业了。"
  },
  AvgCommunicate_121375_Content_3 = {
