  },
  AvgCommunicate_134101_Content_11 = {
    Text = "多亏您的恩赐，我已能彻底看清您的灵魂，知晓世界本来的面貌。"
  },
  AvgCommunicate_134101_Content_12 = {
    Text = "光明，光明……原来世界本是黑暗与混沌，是有神明选择了牺牲，太阳才变作了真实，众生才得以维持存在的幸福……"
  },
  AvgCommunicate_134101_Content_13 = {
    Text = "你是不是读经文读得太多了，感觉你需要稍微冷静一下。"
  },
  AvgCommunicate_134101_Content_14 = {
    Text = "我明白，您希望融入众生之中，不愿端坐于神座之上。"
  },
  AvgCommunicate_134101_Content_15 = {
    Text = "您的无私，您的奉献，您的牺牲……"
  },
  AvgCommunicate_134101_Content_16 = {
    Text = "从今往后我会以最忠诚的……不，以永远的朋友的身份与您交往。"
  },
  AvgCommunicate_134101_Content_17 = {
    Text = "愿这颗永不熄灭的圣心，能为您驱散所有黑暗。"
  },
  AvgCommunicate_134101_Content_2 = {
    Text = "您……您何止是太阳，您原来是宇宙的中心，是世界诞生的起点。"
  },
  AvgCommunicate_134101_Content_3 = {
    Text = "我们都这么熟了，你怎么比以前更加毕恭毕敬了？"
  },
  AvgCommunicate_134101_Content_4 = {
    Text = "因为我明白了，众生未曾尊崇匍匐于您的脚下，只因他们生来愚钝而盲目，无法得见您的本质！"
  },
  AvgCommunicate_134101_Content_5 = {
    Text = "蝼蚁如何见识巨象的全貌？曾经我也只能依靠圣心，短浅地窥视到您力量的冰山一角。"
  },
  AvgCommunicate_134101_Content_6 = {
    Text = "即便这样，圣心也会因此感到针刺般的疼痛，只要再向您的灵魂多看一眼，我便可能会崩溃而亡。"
  },
  AvgCommunicate_134101_Content_7 = {
