  },
  AvgCommunicate_134101_Option_3 = {
    Text = "……好微妙的感觉。"
  },
  AvgCommunicate_134101_Option_7 = {
    Text = "这么严重？"
  },
  AvgCommunicate_134102_Content_1 = {
    Text = "我梦到了故乡的冰雪，还有那些荒芜的废墟。"
  },
  AvgCommunicate_134102_Content_10 = {
    Text = "正因为人类会彼此保留表面友善的样子，这个世界才会更和平一些，我觉得也挺好的。"
  },
  AvgCommunicate_134102_Content_11 = {
