  },
  AvgCommunicate_134103_Content_2 = {
    Text = "在梦境深处，在洋流之底，在亿万眷族的簇拥下，重回到王座之上，为利莫里亚带来繁荣与安宁。"
  },
  AvgCommunicate_134103_Content_20 = {
    Text = "……何人在散播谣言？余只是嫌他们聒噪。"
  },
  AvgCommunicate_134103_Content_21 = {
    Text = "罢了，正好如今余的精神力有了长足的长进，是时候进入一次更深更广的梦境了。"
  },
  AvgCommunicate_134103_Content_22 = {
    Text = "这一次余想去探访遍当今时代的艺术家与诗人之梦，记住，没有要事，不要让人来打扰。"
  },
  AvgCommunicate_134103_Content_23 = {
    Text = "啊？精神大好之后的反应居然是要睡一大觉吗！"
