  },
  AvgCommunicate_134103_Content_5 = {
    Text = "只是余在力量极致增长后受到的感召罢了，至于意义……利莫里亚已经不复存在，也不必再次存在了。"
  },
  AvgCommunicate_134103_Content_6 = {
    Text = "有幸存活的人能够在新世界自由地生活，这很好。"
