  AvgCommunicate_134105_Content_4 = {
    Text = "忧愁……思乡的忧愁已成为灵魂中的烙印，我已习惯和它共存。"
  },
  AvgCommunicate_134105_Content_5 = {
    Text = "不断思念带来痛苦，也会让我永远记得故乡的模样。"
  },
  AvgCommunicate_134105_Content_6 = {
    Text = "那些珊瑚丛生的浅滩，那座巍峨的神殿，与我常常伫立看守的高耸大门……"
  },
  AvgCommunicate_134105_Content_7 = {
    Text = "我记得那些石柱边缘雕刻的纹路，记得王都中每一条宽阔的道路，记得人们祈祷时虔诚幸福的表情。"
  },
  AvgCommunicate_134105_Content_8 = {
    Text = "举行大型祭典时，举国同庆，那是我最忙碌也最满足的时刻。"
  },
  AvgCommunicate_134105_Content_9 = {
    Text = "我曾有幸守护在王驾之前，一同享受万民瞻仰崇敬的眼神，感到自豪而荣耀……那是我最怀念的时刻。"
