  AvgCommunicate_134208_Content_13 = {
    Text = "命运从不辜负慷慨的馈赠者。"
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "我无法触碰您的丝线，但在您为命运而战之时，我的纺轮将永远为您转动。"
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "我已经很久、很久，没有体验过这种感觉了……"
  },
  AvgCommunicate_134208_Content_3 = {
    Text = "什么感觉？"
  },
  AvgCommunicate_134208_Content_4 = {Text = "新奇。"},
  AvgCommunicate_134208_Content_5 = {
    Text = "花蕾静谧的生长，文字在纸张上的交织，云彩在风中温柔的流动……"
  },
  AvgCommunicate_134208_Content_6 = {
    Text = "当然还有人，那些张开的双臂，落下的泪滴，那些如战鼓或雨滴般的心跳……"
  },
  AvgCommunicate_134208_Content_7 = {
    Text = "我比以前看到了更多，但我的眼睛比以前更低。"
  },
  AvgCommunicate_134208_Content_8 = {
    Text = "它不再停留于天空，守密人。它落了下来，落在每一条街道，每一位行人身侧。"
  },
  AvgCommunicate_134208_Content_9 = {
    Text = "现在的我，无需扮演。我可以真正的，作为一个个体而存在。"
