  },
  AvgCommunicate_134268_Option_13 = {Text = "我猜"},
  AvgCommunicate_134268_Option_9 = {Text = "呃"},
  AvgCommunicate_134269_Content_1 = {
    Text = "我的小树苗……"
  },
  AvgCommunicate_134269_Content_10 = {
    Text = "我的身体里，正滋生着触碰最终后，属于“繁衍”的力量。"
  },
  AvgCommunicate_134269_Content_11 = {
    Text = "多么甜美，多么丰润……啊，我有些不甘于对着这小小的金属块与你说话了。"
  },
  AvgCommunicate_134269_Content_12 = {
    Text = "泰旖丝？"
  },
  AvgCommunicate_134269_Content_13 = {
    Text = "到我的身边来吧，小树苗，就现在，立刻。"
