  AvgCommunicate_137645_Option_2 = {
    Text = "怎么了？"
  },
  AvgCommunicate_137646_Content_1 = {
    Text = "守密人，得知你将要远行参加调查，我特意为你撰写了一部作品。"
  },
  AvgCommunicate_137646_Content_10 = {
