  },
  AvgCommunicate_137646_Content_11 = {
    Text = "每一缕纺线，皆有其命定的主人。每一篇故事，也自有它的读者。"
  },
  AvgCommunicate_137646_Content_12 = {
    Text = "一个利于传播的名字，能让这些优秀的故事触及到更多的应当触及到的人。"
