  AvgCommunicate_141374_Content_3 = {
    Text = "你大概不知道这意味着什么，在我足够强大之前，厄波扬斯其实始终无法摆脱那个古老存在的控制。"
  },
  AvgCommunicate_141374_Content_4 = {
