  },
  AvgCommunicate_141374_Content_9 = {Text = "不。"},
  AvgCommunicate_141374_Option_2 = {
    Text = "有点不习惯"
  },
  AvgCommunicate_141374_Option_6 = {Text = "难道"},
  AvgCommunicate_143429_Content_1 = {
    Text = "虽然这些膜拜伪神的邪教徒蠢得让人发笑，但不得不说，他们有些人的品味还算不错。"
  },
  AvgCommunicate_143429_Content_10 = {
