    Text = "%player%%sirormadam%，我遇到了一点小小的问题，想要请你帮个忙。"
  },
  AvgCommunicate_66984_Content_10 = {
    Text = "但我回复他说，我已经有舞伴了。"
  },
  AvgCommunicate_66984_Content_11 = {
    Text = "实际上，我现在才来找我可爱的舞伴。"
  },
  AvgCommunicate_66984_Content_12 = {
    Text = "我想，%heorshe%应该不会忍心让我一个人孤零零地去舞会上吧。"
  },
  AvgCommunicate_66984_Content_13 = {
    Text = "你意下如何呢？"
  },
  AvgCommunicate_66984_Content_14 = {
    Text = "我的荣幸，夫人。"
  },
  AvgCommunicate_66984_Content_15 = {
    Text = "看来我要抓紧学习一下舞步礼仪了，免得到时候踩到夫人的脚。"
  },
  AvgCommunicate_66984_Content_16 = {
    Text = "你总是那样可靠又体贴，我的骑士。"
  },
  AvgCommunicate_66984_Content_2 = {
    Text = "什么事难住了我们的索蕾尔夫人？"
  },
  AvgCommunicate_66984_Content_3 = {
    Text = "洗耳恭听。"
  },
  AvgCommunicate_66984_Content_4 = {
    Text = "过几天我要去参加一个晚宴舞会，你懂的，就是一群矜贵又矫情的人在一起无所事事的那种。"
  },
  AvgCommunicate_66984_Content_5 = {
    Text = "恼人的是最近有个毫无礼貌的家伙一直骚扰我，他也要去那场舞会，还高调邀请我做他的舞伴。"
  },
  AvgCommunicate_66984_Content_6 = {
    Text = "还有这种讨厌的人，要不要我帮夫人做掉他。"
  },
  AvgCommunicate_66984_Content_7 = {
    Text = "呵呵呵，你现在越来越会开玩笑了。"
  },
  AvgCommunicate_66984_Content_8 = {
    Text = "可惜现在还不能，大人们的世界就是这样麻烦。不过，我已经拒绝了他的邀请。"
  },
  AvgCommunicate_66984_Content_9 = {
    Text = "那么事情不是解决了？"
  },
  AvgCommunicate_66984_Option_14 = {
    Text = "我的荣幸，夫人。"
  },
  AvgCommunicate_66984_Option_2 = {
    Text = "什么事难住了我们的索蕾尔夫人？"
  },
  AvgCommunicate_66984_Option_3 = {
    Text = "洗耳恭听。"
  },
  AvgCommunicate_66984_Option_6 = {
    Text = "还有这种讨厌的人，要不要我帮夫人做掉他。"
  },
  AvgCommunicate_66984_Option_9 = {
    Text = "那么事情不是解决了？"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "我的小骑士，有了你上次舞会的帮助，现在我已经成功甩掉了那个讨厌的人。"
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "许愿吗？那就许愿美丽的索蕾尔夫人与我共进一场丰盛的烛光晚餐吧。"
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "只有你和我，不需要与任何人应酬。"
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "如你所愿，狡猾的小家伙。"
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "想吃什么？说说看吧，我会陪你一起品尝的。"
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "这真是考验我一个天天吃食堂的人的想象力了，那么就让我尝尝夫人平时最爱吃的东西吧。"
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "呵呵，真是个会讨人欢心的孩子。"
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "那么，我会在我的宅邸等待你的光临。"
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "为了感谢你的热心与慷慨，我希望能为你做些什么，来聊表我的心意。"
  },
  AvgCommunicate_66985_Content_3 = {
    Text = "您太客气了，索蕾尔夫人，我以为我们之间的关系已经不需要说谢谢了。"
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "我的确不喜欢在口头上表达感谢，大部分时间那只是虚伪的客套。"
  },
  AvgCommunicate_66985_Content_5 = {
    Text = "不过，一个向我提出任意请求的机会，你真的不感兴趣吗？"
  },
  AvgCommunicate_66985_Content_6 = {
    Text = "哇哦，任意请求？这要是被那些贵族先生们听见，岂不是要嫉妒死我了。"
  },
  AvgCommunicate_66985_Content_7 = {
    Text = "你总是值得我为你特别优待。"
  },
  AvgCommunicate_66985_Content_8 = {
    Text = "这下真把我难倒了，好纠结啊，豁出去要一套豪宅的话会不会被学校发现呢……"
  },
  AvgCommunicate_66985_Content_9 = {
    Text = "没关系，我会为你处理一切，你可以放心许愿。"
  },
  AvgCommunicate_66985_Option_10 = {
    Text = "许愿吗？"
  },
  AvgCommunicate_66985_Option_14 = {
    Text = "那么就让我尝尝夫人平时最爱吃的东西吧。"
  },
  AvgCommunicate_66985_Option_3 = {
    Text = "您太客气了，索蕾尔夫人。"
