  },
  AvgCommunicate_66985_Option_8 = {
    Text = "这下真把我难倒了……"
  },
  AvgCommunicate_66986_Content_1 = {
    Text = "我与萝坦刚刚打了一场，我们平手。"
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "啊哈哈……我觉得我的杂念也没有那么多，就先算了……"
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "那你也很强。"
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "可惜那个瀑布旁边总是有个人在钓鱼，有点吵闹。"
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "有一次我走出瀑布，想让他小声一点，他吓得把鱼扔在了我的脸上，然后跑掉了。"
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "不知道他下次还会不会来了。"
