  },
  AvgCommunicate_66988_Content_1 = {
    Text = "最近又得了一笔钱，但是差点死了，还好幸运女神永远眷顾我。"
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "结果在我们打斗起来的时候，触发的陷阱不小心打在了他身上。"
