  },
  AvgCommunicate_66989_Content_1 = {
    Text = "守密人，你请教我的关于调查员危机处理方案的问题，我已经整理好了。"
  },
  AvgCommunicate_66989_Content_10 = {
    Text = "我虽然会比那个拉蒙娜更加关切你的需求，但你忘了，我也曾是她。"
