  AvgCommunicate_94500_Content_1 = {
    Text = "多亏您的引荐，结识了奥吉尔阁下后，他为我们介绍了更多的朋友。"
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "奥吉尔阁下还说，骑士的训练比这些要更加复杂繁琐，看来如书中所说，每一位骑士都是十足可敬之人。"
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "确实，奥吉尔是唤醒体之中训练最勤奋的了！"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "我们还发现，作为教官的艾尔瓦阁下哪怕身有残疾，竟然也与我们做着同样的训练。"
  },
  AvgCommunicate_94500_Content_13 = {
    Text = "我们原以为艾尔瓦教官也是一位骑士，但她说自己曾是一名军人。不知军人是一种怎样的职业，想必与骑士同样可敬。"
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "军人就是为国家征战的人，也可以算是一种骑士吧，不过相比骑士严格的道德戒律来看，军人的所作所为并不一定代表了正义。"
  },
  AvgCommunicate_94500_Content_15 = {
    Text = "艾尔瓦也是离开了军队后才发现了这一点，或许现在的生活对她来说更加舒心吧。"
  },
  AvgCommunicate_94500_Content_16 = {
    Text = "我明白了，您的意思是，骑士代表的不是力量，而是一种正义的精神，像艾尔瓦教官、还有您这样的正义之人，也都拥有着骑士的灵魂。"
  },
  AvgCommunicate_94500_Content_18 = {
    Text = "虽然你说得很好，但怎么这么让人害臊呢……"
  },
  AvgCommunicate_94500_Content_2 = {
    Text = "那是好事啊，真为你们高兴。"
  },
  AvgCommunicate_94500_Content_3 = {
    Text = "我们已经和许多唤醒体都见过了面，的确如您所说，他们大多都是友善的人。"
  },
  AvgCommunicate_94500_Content_4 = {
    Text = "想到刚来这里时，我对他人常常抱有警惕怀疑，真是惭愧。"
  },
  AvgCommunicate_94500_Content_5 = {
    Text = "其实也还好，毕竟还是有很多人值得警惕一下……"
  },
  AvgCommunicate_94500_Content_6 = {
    Text = "现在我和卡斯托尔正在和奥吉尔阁下一起，参加艾尔瓦教官的训练课程。"
  },
  AvgCommunicate_94500_Content_7 = {
    Text = "奥吉尔阁下战斗的英姿真是耀眼，不过他本人好像并不习惯被夸赞，真是谦逊的人啊。"
  },
  AvgCommunicate_94500_Content_8 = {
    Text = "哈哈哈，奥吉尔就是很容易害羞啦，你们正常地和他说话就好了。"
  },
  AvgCommunicate_94500_Content_9 = {
    Text = "原来如此，我和卡斯托尔在教会中从未受到过战斗的训练，这样繁重的锻炼真是辛苦，然而奥吉尔阁下居然说他日日如此，这是何等的毅力。"
  },
  AvgCommunicate_94500_Option_11 = {
    Text = "确实，奥吉尔是唤醒体之中训练最勤奋的了！"
  },
  AvgCommunicate_94500_Option_14 = {
