  AvgCommunicate_94501_Content_1 = {
    Text = "尊敬的大人，感谢您为我和卡斯托尔费心准备的屋舍。"
  },
  AvgCommunicate_94501_Content_10 = {
    Text = "卡斯托尔那个家伙喜欢得一天要洗漱五次，被我拦下后变成了一天三次。"
  },
  AvgCommunicate_94501_Content_12 = {
    Text = "洗太多次脸会坏掉的啊！！"
  },
  AvgCommunicate_94501_Content_13 = {
    Text = "不过你们之前都没有用过这些东西吗？没想到提灯教会居然这么小气。"
  },
  AvgCommunicate_94501_Content_14 = {
    Text = "的确没有，不过并非因为教会小气，而是我们身为圣子，一直以来都被要求节制欲望、潜心修行。"
  },
  AvgCommunicate_94501_Content_15 = {
    Text = "我们几乎从未接触过这些科技制品，每日的起居、饮食亦有许多规定。"
  },
  AvgCommunicate_94501_Content_16 = {
    Text = "虽说衣着饮食上大都足够奢华，但除却三餐时间是不能进食的，到达起床时间后更是必需离开寝宫。"
  },
  AvgCommunicate_94501_Content_17 = {
    Text = "小时候我就常常幻想着什么时候可以不用早起，一整天都能想吃什么就吃什么。"
  },
  AvgCommunicate_94501_Content_18 = {
    Text = "这几天我已经屡次在下午看到一位少女端着食物从走廊经过，看起来我那梦想中的生活在这里已经是日常了。"
  },
  AvgCommunicate_94501_Content_19 = {
    Text = "啊，那大概是墨菲去拿小蛋糕了吧……你们的生活还真是辛苦啊。"
  },
  AvgCommunicate_94501_Content_2 = {
    Text = "我听到卡斯托尔说屋舍中被特意增添了一张床铺，就知道一定是您的手笔。"
  },
  AvgCommunicate_94501_Content_20 = {
    Text = "一切都过去了，那些错误和扭曲都会留在过去，我们会以崭新的姿态走上正确的道路，请您见证。"
  },
  AvgCommunicate_94501_Content_21 = {
    Text = "太客气了，有问题找我就好，你们这样的态度已经比有些唤醒体不知道省心多少倍了！"
  },
  AvgCommunicate_94501_Content_3 = {
    Text = "我们从小在教会中就习惯于一同在寝宫中起居，听闻此地的寝居规定为一人一间后还略有忧心。"
  },
  AvgCommunicate_94501_Content_4 = {
    Text = "如今看到您心细如发地为我们考量，实在发觉当日泰旖丝女士建议我们投奔于您的正确。"
  },
  AvgCommunicate_94501_Content_5 = {
    Text = "哈哈，小事小事，你们来这里之后住得还习惯吗？"
  },
  AvgCommunicate_94501_Content_6 = {
    Text = "承蒙照拂，一切都好，此地的寝宫虽然狭小如侍女的屋舍，但陈设用品都很齐全，适应之后也颇有温馨之感。"
  },
  AvgCommunicate_94501_Content_7 = {
    Text = "啊哈哈，是吗，那就好，那就好……"
  },
  AvgCommunicate_94501_Content_8 = {
    Text = "我们已经慢慢学会在无人服侍下生活，您不用为我们担心，不如说这是我们两个多年来梦寐以求的。"
  },
  AvgCommunicate_94501_Content_9 = {
    Text = "尤其是屋内配备的洁面膏真是神奇，按照说明使用后竟能产生许多云朵般的泡沫，那份洁牙膏的味道也十分清新。"
  },
  AvgCommunicate_94501_Option_19 = {
    Text = "啊，那大概是墨菲去拿小蛋糕了吧……"
  },
  AvgCommunicate_94501_Option_21 = {
    Text = "太客气了。"
  },
  AvgCommunicate_94501_Option_5 = {
    Text = "小事小事。"
  },
  AvgCommunicate_94501_Option_7 = {
    Text = "啊哈哈，是吗，那就好，那就好……"
  },
  AvgCommunicate_94502_Content_1 = {
    Text = "冒昧叨扰，可否能请您为我们略做引荐……"
